///
/// Recursively explores check-giving moves. Non-check leaves are evaluated with
/// static analysis; the result is `Some(Unwinnable)` only if every such leaf is
/// statically unwinnable. At depth 0 the first move is explored even without
/// giving check.
pub(crate) fn check_chain_search(
    board: &Board,
    visited: &mut FxHashSet<Board>,
    depth: u32,
) -> Option<Winnability> {
    if depth > 16 {
        return None;
    }
    visited.insert(*board);

    let mut legal_moves = MoveGen::new_legal(board).peekable();

    if legal_moves.peek().is_none() {
        if board.side_to_move() == Color::Black && *board.checkers() != EMPTY {
            return Some(Winnability::Winnable { helpmate: vec![] });
        }
        return Some(Winnability::Unwinnable);
    }

    for m in legal_moves {
        let new_board = board.make_move_new(m);
        if visited.contains(&new_board) {
            continue;
        }
        if *new_board.checkers() != EMPTY || depth == 0 {
            match check_chain_search(&new_board, visited, depth + 1) {
                w @ Some(Winnability::Winnable { .. }) => return w,
                None => return None,
                Some(Winnability::Unwinnable) => continue,
            }
        }
        if !is_statically_unwinnable(&new_board) {
            return None;
        }
    }

    Some(Winnability::Unwinnable)
}

/// Returns `true` if static analysis can prove the position is unwinnable for
/// White.
///
/// Runs [`Analysis::saturate`] under different assumptions about which pieces
/// can be captured, branching on the fate of pieces that are both steady and
/// capturable (`first_steady_capturable`). Returns `true` only if every
/// scenario rules out a checkmate.
pub(crate) fn is_statically_unwinnable(board: &Board) -> bool {
    if board.en_passant().is_some() {
        return false;
    }

    let mut analysis = Analysis::new(*board);

    let white = board.color_combined(Color::White);
    if white.popcnt() == 2 {
        let last_white_piece = white & !board.pieces(Piece::King);
        analysis.uncapturable_while_steady = Some(last_white_piece);
    }

    analysis.saturate();

    if !analysis.black_could_get_mated() {
        return true;
    }

    if let Some(squares) = analysis.first_steady_capturable {
        for s in squares {
            let mut analysis = Analysis::new(*board);
            analysis.uncapturable_while_steady = Some(BitBoard::from_square(s));
            analysis.saturate();

            if analysis.black_could_get_mated() {
                continue;
            }

            // Case B: the piece can only be captured while still on its starting square.
            // If this also rules out mate, no valid scenario exists and the position is
            // unwinnable.
            let mut analysis = Analysis::new(*board);
            analysis.capturable_only_while_steady = Some(BitBoard::from_square(s));
            analysis.saturate();

            if !analysis.black_could_get_mated() {
                return true;
            }
        }
    }

    // TODO: Generalize this for more than 2 squares (mainly aesthetic; could also
    // improve completeness).
    if let Some(squares) = analysis.first_steady_capturable {
        if squares.popcnt() == 2 {
            let s1 = squares.to_square();
            let s2 = (squares & !BitBoard::from_square(s1)).to_square();

            let mut analysis = Analysis::new(*board);
            analysis.uncapturable_while_steady = Some(squares);
            analysis.saturate();

            if analysis.black_could_get_mated() {
                return false;
            }

            let mut analysis = Analysis::new(*board);
            analysis.uncapturable_while_steady = Some(BitBoard::from_square(s1));
            analysis.capturable_only_while_steady = Some(BitBoard::from_square(s2));
            analysis.saturate();

            if analysis.black_could_get_mated() {
                return false;
            }

            let mut analysis = Analysis::new(*board);
            analysis.capturable_only_while_steady = Some(BitBoard::from_square(s1));
            analysis.uncapturable_while_steady = Some(BitBoard::from_square(s2));
            analysis.saturate();

            if analysis.black_could_get_mated() {
                return false;
            }

            let mut analysis = Analysis::new(*board);
            analysis.capturable_only_while_steady = Some(squares);
            analysis.saturate();

            return !analysis.black_could_get_mated();
        }

/// Most fields below are *approximations* of some true game-theoretic
/// property of the position (e.g. "this piece can reach that square").
///
/// - An **over-approximation** may wrongly *include* an element (false
///   positive) but never wrongly excludes one. The safe inference runs on
///   absence: if `x` is not in the field, `x` definitely lacks the property.
///
/// - An **under-approximation** may wrongly *exclude* an element (false
///   negative) but never wrongly includes one. The safe inference runs on
///   presence: if `x` is in the field, `x` definitely has the property.
///
/// Both kinds only reach their stated guarantee *after saturation completes*
/// ([`Analysis::saturate`]); mid-saturation, neither direction can be relied
/// on.
pub(crate) struct Analysis {

            get_king_moves(mating_square) & black_king_region & !visited_region;
        let (blockers, blocking_region) = self.blockers(escaping_squares);
        let n = blockers.popcnt().min(blocking_region.popcnt());

        // Try all ways to assign n black pieces to n squares in blocking_region.
        for covered_by_black in subsets_of_size(blocking_region, n) {
            let remaining = escaping_squares & !covered_by_black;
            // Check if the white king can cover all remaining squares from one position.
            if remaining == EMPTY {
                return true;
            }
            let candidate_king_squares =
                remaining.into_iter().fold(EMPTY, |acc, r| acc | get_king_moves(r))
                    & !(BitBoard::from_square(mating_square) | get_king_moves(mating_square));
            if (candidate_king_squares & white_king_reachable)
                .into_iter()
                .any(|s| get_king_moves(s) & remaining == remaining)
            {
                return true;
            }
        }
    }

    false
}

/// Returns the white non-king pieces that can attack `region` (visitors),
/// and the subset of `region` they can attack (visited_region). Only pieces
/// that can move away from their starting square are considered.
///
/// Must be called after saturation.
fn visitors(&self, region: BitBoard) -> (BitBoard, BitBoard) {
    let mut visitors = EMPTY;
    let mut visited_region = EMPTY;
    for s in *self.board.color_combined(Color::White) {
        let piece = self.board.piece_on(s).unwrap();
        if piece == Piece::King {
            continue;
        }
        if self.reachable[s.to_index()] == BitBoard::from_square(s) {
            continue;
        }
        for t in self.reachable[s.to_index()] {
            let attacked_by_piece = get_piece_attacks(piece, Color::White, t, !self.clear);
            if region & attacked_by_piece != EMPTY {
                visitors |= BitBoard::from_square(s);
                visited_region |= region & attacked_by_piece;
            }

/// Checks that `winnability(board, intended_winner)` agrees with
/// `expected_winnable`, and that a `Winnable` result's `helpmate` actually
/// leads to a checkmate by `intended_winner`.
///
/// Also checks that `is_unwinnable_fast` is sound: it is incomplete by
/// design, so it can't be expected to match `expected_winnable` exactly, but
/// it must never claim unwinnable for a position that's actually winnable.
fn check_winnability(board: &Board, intended_winner: Color, expected_winnable: bool) {
    match winnability(board, intended_winner) {
        Some(Winnability::Winnable { helpmate }) => {
            let mated_board = helpmate.iter().fold(*board, |b, &m| b.make_move_new(m));
            assert_eq!(mated_board.status(), BoardStatus::Checkmate);
            assert_eq!(mated_board.side_to_move(), !intended_winner);
            assert!(expected_winnable);
        }
        Some(Winnability::Unwinnable) => assert!(!expected_winnable),
        None => panic!("Undetermined: {board}"),
    }

    if is_unwinnable_fast(board, intended_winner) {
        assert!(!expected_winnable, "is_unwinnable_fast wrongly claimed unwinnable: {board}");
    }
}

/// Checks every position in `data` against its expected classification.
///
/// Each line is supposed to be `<2-char classification> <FEN>`, where the first
/// character is `W` if White can win, `-` if not, and likewise for Black/the
/// second character.
fn check_positions(data: &str) {
    let entries: Vec<&str> =
        data.lines().filter(|line| !line.trim().is_empty() && !line.starts_with('#')).collect();

    entries.par_iter().for_each(|line| {
        let parts: Vec<&str> = line.splitn(2, ' ').collect();
        assert_eq!(parts.len(), 2, "Invalid line format: {}", line);

        let expected = parts[0];
        let fen = parts[1];

        let board = Board::from_str(fen).unwrap_or_else(|_| panic!("Failed to parse FEN: {}", fen));

        check_winnability(&board, Color::White, expected.starts_with("W"));
        check_winnability(&board, Color::Black, expected.ends_with("B"));
    });
}

