    if (self.pieces(Piece::King) & self.color_combined(Color::White)).popcnt() != 1 {
        return false;
    }

    // make sure there is exactly one black king
    if (self.pieces(Piece::King) & self.color_combined(Color::Black)).popcnt() != 1 {
        return false;
